import 'package:flutter/material.dart';
import '../constants/app_constants.dart';
class StatCard extends StatelessWidget { const StatCard({required this.title, required this.value, required this.icon, this.footer, super.key}); final String title, value; final IconData icon; final String? footer; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, color: AppConstants.gold), const SizedBox(height: 12), Text(title, style: const TextStyle(color: Colors.white60)), Text(value, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)), if (footer != null) Text(footer!, style: const TextStyle(color: Colors.white54, fontSize: 12))]))); }
